-- Room createAllTables from the f87b866af integration preview, including its identity hash.
CREATE TABLE IF NOT EXISTS `user_profiles` (`id` TEXT NOT NULL, `revision` INTEGER NOT NULL, `name` TEXT NOT NULL, `primaryGoal` TEXT NOT NULL, `experienceLevel` TEXT NOT NULL, `preferredDurationMinutes` INTEGER NOT NULL, `daysPerWeek` INTEGER NOT NULL, `availableEquipmentJson` TEXT NOT NULL, `preferredUnit` TEXT NOT NULL, `musclePrioritiesJson` TEXT NOT NULL, `excludedExerciseIdsJson` TEXT NOT NULL, `onboardingCompleted` INTEGER NOT NULL DEFAULT 0, `trainingConstraintsJson` TEXT NOT NULL DEFAULT '', `returningAfterBreakWeeks` INTEGER NOT NULL DEFAULT 0, `confirmedStartingLoadsJson` TEXT NOT NULL DEFAULT '', `fitnessGoalsJson` TEXT NOT NULL DEFAULT '', `movementCapabilitiesJson` TEXT NOT NULL DEFAULT '{}', `themePreference` TEXT NOT NULL DEFAULT 'SYSTEM', `gender` TEXT NOT NULL DEFAULT 'UNSPECIFIED', `illustrationPreference` TEXT NOT NULL DEFAULT 'AUTOMATIC', `activeConditionsJson` TEXT NOT NULL DEFAULT '[]', PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `workout_sessions` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `startedAtTimestamp` INTEGER NOT NULL, `completedAtTimestamp` INTEGER, `targetDurationMinutes` INTEGER NOT NULL, `actualDurationMinutes` INTEGER NOT NULL, `weightUnit` TEXT NOT NULL, `status` TEXT NOT NULL, `origin` TEXT NOT NULL DEFAULT 'PLANNER', `sourceTemplateId` TEXT, `focusMusclesJson` TEXT NOT NULL, `notes` TEXT NOT NULL, `conditionContextJson` TEXT, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_workout_sessions_status_completedAtTimestamp` ON `workout_sessions` (`status`, `completedAtTimestamp`);
CREATE TABLE IF NOT EXISTS `workout_exercises` (`id` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `exerciseId` TEXT NOT NULL, `orderIndex` INTEGER NOT NULL, `exerciseType` TEXT NOT NULL, `targetSets` INTEGER NOT NULL, `targetRepMin` INTEGER, `targetRepMax` INTEGER, `targetWeight` REAL, `targetAssistanceWeight` REAL, `targetDurationSeconds` INTEGER, `targetDistanceMeters` REAL, `restSeconds` INTEGER NOT NULL, `notes` TEXT NOT NULL, `effortMinRir` INTEGER, `effortMaxRir` INTEGER, `restClass` TEXT, `restTargetSource` TEXT, `purpose` TEXT NOT NULL DEFAULT 'ORDINARY', PRIMARY KEY(`id`), FOREIGN KEY(`sessionId`) REFERENCES `workout_sessions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_workout_exercises_sessionId` ON `workout_exercises` (`sessionId`);
CREATE TABLE IF NOT EXISTS `workout_sets` (`id` TEXT NOT NULL, `workoutExerciseId` TEXT NOT NULL, `setNumber` INTEGER NOT NULL, `exerciseType` TEXT NOT NULL, `targetReps` INTEGER, `completedReps` INTEGER, `targetWeight` REAL, `completedWeight` REAL, `targetAssistanceWeight` REAL, `completedAssistanceWeight` REAL, `targetDurationSeconds` INTEGER, `completedDurationSeconds` INTEGER, `targetDistanceMeters` REAL, `completedDistanceMeters` REAL, `isCompleted` INTEGER NOT NULL, `rpe` REAL, `rir` INTEGER, `feltManageable` INTEGER, `completedAtTimestamp` INTEGER, `stoppedAtTimestamp` INTEGER, `stopReason` TEXT, `type` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`workoutExerciseId`) REFERENCES `workout_exercises`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_workout_sets_workoutExerciseId` ON `workout_sets` (`workoutExerciseId`);
CREATE TABLE IF NOT EXISTS `workout_templates` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `notes` TEXT NOT NULL, `createdAtTimestamp` INTEGER NOT NULL, `updatedAtTimestamp` INTEGER NOT NULL, `weightUnit` TEXT, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `workout_template_exercises` (`templateId` TEXT NOT NULL, `orderIndex` INTEGER NOT NULL, `exerciseId` TEXT NOT NULL, `exerciseType` TEXT NOT NULL, `targetSets` INTEGER NOT NULL, `targetRepMin` INTEGER, `targetRepMax` INTEGER, `targetWeight` REAL, `targetAssistanceWeight` REAL, `targetDurationSeconds` INTEGER, `targetDistanceMeters` REAL, `restSeconds` INTEGER NOT NULL, `notes` TEXT NOT NULL, `effortMinRir` INTEGER, `effortMaxRir` INTEGER, `restClass` TEXT, `restTargetSource` TEXT, `purpose` TEXT NOT NULL DEFAULT 'ORDINARY', PRIMARY KEY(`templateId`, `orderIndex`), FOREIGN KEY(`templateId`) REFERENCES `workout_templates`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_workout_template_exercises_templateId` ON `workout_template_exercises` (`templateId`);
CREATE TABLE IF NOT EXISTS `weekly_dose_ledger_state` (`profileId` TEXT NOT NULL, `weekStartEpochDay` INTEGER NOT NULL, `timeZoneId` TEXT NOT NULL, `policyVersion` TEXT NOT NULL, `catalogVersion` TEXT NOT NULL, `reviewPolicyVersion` INTEGER NOT NULL, `ledgerPayload` TEXT NOT NULL, `sourceFingerprint` TEXT NOT NULL, `generatedAtTimestamp` INTEGER NOT NULL, PRIMARY KEY(`profileId`, `weekStartEpochDay`, `timeZoneId`, `policyVersion`));
CREATE TABLE IF NOT EXISTS `workout_recommendation_records` (`sessionId` TEXT NOT NULL, `validatorVersion` TEXT NOT NULL, `durationEstimatorVersion` TEXT NOT NULL, `outcome` TEXT NOT NULL, `reviewedPathEnabled` INTEGER NOT NULL, `catalogVersion` TEXT, `reviewPolicyVersion` INTEGER NOT NULL, `trainingPolicyVersion` TEXT, `ledgerPolicyVersion` TEXT, `programStatePolicyVersion` TEXT, `adaptationState` TEXT, `weekStartEpochDay` INTEGER, `timeZoneId` TEXT, `profileRevision` INTEGER NOT NULL, `contextIdentity` TEXT NOT NULL, `reasonCodes` TEXT NOT NULL, `doseAccounting` TEXT NOT NULL, `recordedAtTimestamp` INTEGER NOT NULL, `programAssociationDigest` TEXT, `conditionContextDigest` TEXT, PRIMARY KEY(`sessionId`), FOREIGN KEY(`sessionId`) REFERENCES `workout_sessions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `deload_preferences` (`profileId` TEXT NOT NULL, `revision` INTEGER NOT NULL, `offerId` TEXT, `source` TEXT, `policyVersion` TEXT, `status` TEXT, `decidedAtEpochMillis` INTEGER, `sessionId` TEXT, `lastHandledReturnKey` TEXT, PRIMARY KEY(`profileId`));
CREATE TABLE IF NOT EXISTS `program_enrollments` (`profileId` TEXT NOT NULL, `programId` TEXT NOT NULL, `revision` INTEGER NOT NULL, `lifecyclePolicyVersion` TEXT NOT NULL, `configurationPolicyVersion` TEXT NOT NULL, `primaryGoal` TEXT NOT NULL, `goals` TEXT NOT NULL, `sessionsPerWeek` INTEGER NOT NULL, `status` TEXT NOT NULL, `createdAtTimestamp` INTEGER NOT NULL, `updatedAtTimestamp` INTEGER NOT NULL, PRIMARY KEY(`profileId`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_program_enrollments_programId` ON `program_enrollments` (`programId`);
CREATE TABLE IF NOT EXISTS `program_session_associations` (`sessionId` TEXT NOT NULL, `profileId` TEXT NOT NULL, `programId` TEXT NOT NULL, `enrollmentRevision` INTEGER NOT NULL, `lifecyclePolicyVersion` TEXT NOT NULL, `configurationPolicyVersion` TEXT NOT NULL, `primaryGoal` TEXT NOT NULL, `goals` TEXT NOT NULL, `sessionsPerWeek` INTEGER NOT NULL, `slotOrdinal` INTEGER NOT NULL, `blockNumber` INTEGER NOT NULL, `weekNumber` INTEGER NOT NULL, `sessionInWeek` INTEGER NOT NULL, `objective` TEXT NOT NULL, PRIMARY KEY(`sessionId`), FOREIGN KEY(`sessionId`) REFERENCES `workout_sessions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE UNIQUE INDEX IF NOT EXISTS `index_program_session_associations_programId_slotOrdinal` ON `program_session_associations` (`programId`, `slotOrdinal`);
CREATE INDEX IF NOT EXISTS `index_program_session_associations_profileId` ON `program_session_associations` (`profileId`);
CREATE TABLE IF NOT EXISTS `condition_reassessment_pending` (`profileId` TEXT NOT NULL, `conditionId` TEXT NOT NULL, `exerciseId` TEXT NOT NULL, `eventId` TEXT NOT NULL, `stoppedContextIdentity` TEXT NOT NULL, `responsePolicyVersion` INTEGER NOT NULL, `stoppedAtTimestamp` INTEGER NOT NULL, `sourceSetId` TEXT, PRIMARY KEY(`profileId`, `conditionId`, `exerciseId`));
